from collections import deque


def nearestShelter(n, edges, shelters):
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    ans = [-1] * n
    q = deque()
    for s in shelters:
        ans[s] = 0
        q.append(s)
    while q:
        u = q.popleft()
        for v in adj[u]:
            if ans[v] == -1:
                ans[v] = ans[u] + 1
                q.append(v)
    return ans
